<template>
  <div class="page-shell"><div class="page-heading"><div><h1>房屋与智慧门牌</h1><p>一房一码，聚合房东、承租人、居住证与巡查档案。</p></div><el-button v-if="auth.role==='ADMIN'" type="primary" @click="open()"><el-icon><Plus/></el-icon>新增房屋</el-button></div>
    <section class="panel"><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="楼栋、房号或房东" style="width:240px"/><el-select v-model="query.usageStatus" clearable placeholder="房屋状态" style="width:140px"><el-option v-for="(v,k) in statuses" :key="k" :label="v" :value="k"/></el-select><el-button @click="load"><el-icon><Search/></el-icon>查询</el-button><el-button @click="reset">重置</el-button></div>
      <div class="table-wrap"><el-table :data="page.records" v-loading="loading"><el-table-column prop="communityName" label="社区" min-width="120"/><el-table-column prop="buildingName" label="楼栋" min-width="120"/><el-table-column label="房屋" min-width="120"><template #default="s"><b>{{s.row.unitNo}}{{s.row.roomNo}}</b><small class="sub">{{s.row.floorNo}}层 · {{s.row.area||'—'}}㎡</small></template></el-table-column><el-table-column prop="ownerName" label="房东" min-width="100"/><el-table-column prop="houseType" label="户型" min-width="110"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="statusType[s.row.usageStatus]">{{statuses[s.row.usageStatus]}}</el-tag></template></el-table-column><el-table-column label="二维码" width="90"><template #default="s"><el-tag :type="s.row.qrEnabled?'success':'info'" effect="plain">{{s.row.qrEnabled?'有效':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="260" fixed="right"><template #default="s"><el-button link type="primary" @click="showQr(s.row)">二维码</el-button><el-button link @click="showArchive(s.row)">综合档案</el-button><el-button v-if="auth.role==='ADMIN'" link type="primary" @click="open(s.row)">编辑</el-button><el-popconfirm v-if="auth.role==='ADMIN'" title="重新生成后旧二维码将失效，继续？" @confirm="regenerate(s.row)"><template #reference><el-button link type="warning">重置码</el-button></template></el-popconfirm></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.pageNum" :total="page.total" layout="total,prev,pager,next" @current-change="load"/></div></div></section>
    <el-dialog v-model="dialog" :title="editing?'编辑房屋':'新增房屋'" width="640px"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="所属楼栋" prop="buildingId"><el-select v-model="form.buildingId" filterable style="width:100%"><el-option v-for="b in buildings" :key="b.id" :label="b.label" :value="b.id"/></el-select></el-form-item><el-form-item label="房东"><el-select v-model="form.ownerId" clearable filterable style="width:100%"><el-option v-for="u in owners" :key="u.id" :label="u.label" :value="u.id"/></el-select></el-form-item><el-row :gutter="14"><el-col :span="8"><el-form-item label="单元" prop="unitNo"><el-input v-model="form.unitNo"/></el-form-item></el-col><el-col :span="8"><el-form-item label="房号" prop="roomNo"><el-input v-model="form.roomNo"/></el-form-item></el-col><el-col :span="8"><el-form-item label="楼层" prop="floorNo"><el-input-number v-model="form.floorNo" :min="1"/></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="12"><el-form-item label="面积"><el-input-number v-model="form.area" :min="1" :precision="2"/></el-form-item></el-col><el-col :span="12"><el-form-item label="户型"><el-input v-model="form.houseType"/></el-form-item></el-col></el-row><el-form-item label="房屋状态"><el-select v-model="form.usageStatus" style="width:100%"><el-option v-for="(v,k) in statuses" :key="k" :label="v" :value="k"/></el-select></el-form-item><el-form-item label="二维码"><el-switch v-model="form.qrEnabled" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
    <el-dialog v-model="qrDialog" title="智慧门牌二维码" width="430px" align-center><div class="qr-box"><img v-if="selected" :src="qrUrl(selected)"/><b>{{selected?.communityName}} · {{selected?.buildingName}}</b><span>{{selected?.unitNo}}{{selected?.roomNo}}</span><p>使用手机相机或微信扫描，进入房屋电子身份页面</p><a v-if="selected" :href="qrUrl(selected)" download="智慧门牌.png">下载二维码</a></div></el-dialog>
    <el-drawer v-model="archiveDrawer" title="一房一档" size="620px"><div v-loading="archiveLoading" class="archive"><el-descriptions v-if="archive.house" :column="2" border><el-descriptions-item label="房屋">{{archive.house.communityName}} / {{archive.house.buildingName}} / {{archive.house.unit_no}}{{archive.house.room_no}}</el-descriptions-item><el-descriptions-item label="房东">{{archive.house.ownerName||'未绑定'}}</el-descriptions-item><el-descriptions-item label="房东电话">{{archive.house.ownerPhone||'—'}}</el-descriptions-item><el-descriptions-item label="状态">{{statuses[archive.house.usage_status]}}</el-descriptions-item></el-descriptions><h3>租住记录</h3><el-table :data="archive.tenants" size="small"><el-table-column prop="name" label="姓名"/><el-table-column prop="phone" label="手机号"/><el-table-column prop="status" label="状态"/></el-table><h3>巡查记录</h3><el-table :data="archive.patrols" size="small"><el-table-column prop="title" label="任务"/><el-table-column prop="policeName" label="民警"/><el-table-column prop="status" label="状态"/></el-table></div></el-drawer>
  </div>
</template>
<script setup>
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import http from'../api/http';import{useAuthStore}from'../stores/auth'
const auth=useAuthStore(),statuses={VACANT:'空置',SELF_OCCUPIED:'自住',RENTED:'出租中'},statusType={VACANT:'info',SELF_OCCUPIED:'primary',RENTED:'success'};const query=reactive({pageNum:1,pageSize:10,keyword:'',usageStatus:''}),page=reactive({records:[],total:0}),loading=ref(false),dialog=ref(false),editing=ref(null),formRef=ref(),buildings=ref([]),owners=ref([]),qrDialog=ref(false),selected=ref(null),archiveDrawer=ref(false),archiveLoading=ref(false),archive=reactive({});const blank=()=>({buildingId:null,ownerId:null,unitNo:'1单元',roomNo:'',floorNo:1,area:80,houseType:'两室一厅',usageStatus:'VACANT',qrEnabled:1,remark:''}),form=reactive(blank()),rules={buildingId:[{required:true,message:'请选择楼栋'}],unitNo:[{required:true,message:'请输入单元'}],roomNo:[{required:true,message:'请输入房号'}],floorNo:[{required:true,message:'请输入楼层'}]}
onMounted(async()=>{buildings.value=await http.get('/buildings/options');owners.value=await http.get('/users/options',{params:{role:'OWNER'}});load()});async function load(){loading.value=true;try{Object.assign(page,await http.get('/houses',{params:query}))}finally{loading.value=false}}function reset(){query.keyword='';query.usageStatus='';query.pageNum=1;load()}function open(row){editing.value=row?.id||null;Object.assign(form,blank(),row||{});dialog.value=true}async function save(){await formRef.value.validate();editing.value?await http.put(`/houses/${editing.value}`,form):await http.post('/houses',form);ElMessage.success('保存成功');dialog.value=false;load()}function showQr(row){selected.value=row;qrDialog.value=true}function qrUrl(row){return `/api/public/doorplates/${row.publicId}/qr.png?baseUrl=${encodeURIComponent(location.origin)}`}async function regenerate(row){const d=await http.put(`/houses/${row.id}/regenerate-qr`);row.publicId=d.publicId;ElMessage.success('二维码已重新生成');load()}async function showArchive(row){archiveDrawer.value=true;archiveLoading.value=true;try{Object.assign(archive,await http.get(`/houses/${row.id}/archive`))}finally{archiveLoading.value=false}}
</script>
<style scoped>.sub{display:block;color:#91a3ac;margin-top:4px}.qr-box{text-align:center;display:flex;flex-direction:column;align-items:center;gap:8px}.qr-box img{width:280px;height:280px;border:10px solid #f2f7f7}.qr-box span,.qr-box p{color:#8297a1;font-size:12px}.qr-box p{margin:5px 0}.qr-box a{color:#0e8a7a;text-decoration:none}.archive h3{font-size:14px;margin:25px 0 10px}</style>
